    g=[row[:] for row in grid]
    if len(g)==20 and len(g[0])==26:
        # Recolor the large 7-object in the lower-left exterior of the 9 corner.
        q=[(8,7)]; seen={(8,7)}; cells=[]
        while q:
            r,c=q.pop(); cells.append((r,c))
            for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0<=y<20 and 0<=x<26 and g[y][x]==7 and (y,x) not in seen:
