def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts: return [row[:] for row in grid]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    out=[row[:] for row in grid]
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if out[r][c] == bg: out[r][c]=2
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if out[r][c] == bg: out[r][c]=2
    # If a completed rectangular frame encloses a repeated straight run,
    # connect the run through the frame.
    perimeter={(r0,c) for c in range(c0,c1+1)}|{(r1,c) for c in range(c0,c1+1)}|{(r,c0) for r in range(r0,r1+1)}|{(r,c1) for r in range(r0,r1+1)}
    closed=all(grid[r][c] != bg for r,c in perimeter)
    if closed:
        inner=[(r,c) for r,c in pts if r0<r<r1 and c0<c<c1]
        cols={c for r,c in inner}
        rows={r for r,c in inner}
        if len(cols)==1 and len(inner)>=3:
            c=next(iter(cols))
            for r in range(r0,r1+1):
                if out[r][c]==bg: out[r][c]=2
        elif len(rows)==1 and len(inner)>=3:
            r=next(iter(rows))
            for c in range(c0,c1+1):
                if out[r][c]==bg: out[r][c]=2
    return out

