def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete the perimeter of the foreground bounding box.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] == bg:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] == bg:
                out[r][c] = 2

    # Complete internal aligned runs only when at least two foreground marks
    # lie strictly inside the box on that row/column. Edge marks can extend
    # the run, but do not by themselves trigger it.
    for c in range(c0 + 1, c1):
        internal = [r for r in range(r0 + 1, r1) if grid[r][c] != bg]
        if len(internal) >= 2:
            all_marks = [r for r in range(r0, r1 + 1) if grid[r][c] != bg]
            for r in range(min(all_marks), max(all_marks) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    for r in range(r0 + 1, r1):
        internal = [c for c in range(c0 + 1, c1) if grid[r][c] != bg]
        if len(internal) >= 2:
            all_marks = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
            for c in range(min(all_marks), max(all_marks) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    pieces = []
    # The shape consists of 2x2 squares and L triominoes. The output
    # color marks the square or the L's missing corner.
    for r in range(rows - 1):
        for c in range(cols - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if square <= cells:
                pieces.append((1, square))
            for missing, color in [((0, 0), 2), ((1, 0), 3), ((0, 1), 4)]:
                triomino = {
                    (r + dr, c + dc)
                    for dr in (0, 1) for dc in (0, 1)
                    if (dr, dc) != missing
                }
                if triomino <= cells:
                    pieces.append((color, triomino))

    by_cell = {cell: [] for cell in cells}
    for i, (_, piece) in enumerate(pieces):
        for cell in piece:
            by_cell[cell].append(i)

    solution = None
    def search(remaining, chosen):
        nonlocal solution
        if not remaining:
            solution = chosen
            return True
        cell = min(remaining, key=lambda p: sum(pieces[i][1] <= remaining for i in by_cell[p]))
        for i in by_cell[cell]:
            color, piece = pieces[i]
            if piece <= remaining and search(remaining - piece, chosen + [(color, piece)]):
                return True
        return False

    if not search(cells, []):
        raise ValueError("No valid square/L-triomino tiling found")
    result = [[0] * cols for _ in range(rows)]
    for color, piece in solution:
        for r, c in piece:
            result[r][c] = color
    return result

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = [[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c] or color == bg:
                continue
            q = deque([(r,c)])
            seen[r][c] = True
            cells = []
            while q:
                y,x = q.popleft()
                cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx = y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny,nx))
            if len(cells) >= 8:
                r0=min(y for y,x in cells); r1=max(y for y,x in cells)
                c0=min(x for y,x in cells); c1=max(x for y,x in cells)
                for y in range(r0,r1+1):
                    for x in range(c0,c1+1):
                        out[y][x]=color
    return out

