from collections import deque

def _components(g):
    h, w = len(g), len(g[0])
    seen = set(); out = []
    for r in range(h):
        for c in range(w):
            col = g[r][c]
            if col == g[0][0] or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); pts=[]
            while q:
                y,x=q.popleft(); pts.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==col:
                        seen.add((ny,nx)); q.append((ny,nx))
            out.append((col,pts))
    return out

def _norm(pts):
    minr=min(r for r,c in pts); minc=min(c for r,c in pts)
    return frozenset((r-minr,c-minc) for r,c in pts)

def _variants(shape):
    pts=list(shape); result=set()
    for flip in (1,-1):
        for k in range(4):
            arr=[]
            for r,c in pts:
                x,y=r, c*flip
                for _ in range(k): x,y=y,-x
                arr.append((x,y))
            mr=min(x for x,y in arr); mc=min(y for x,y in arr)
            result.add(frozenset((x-mr,y-mc) for x,y in arr))
    return result

def transform(grid):
    g=[row[:] for row in grid]
    comps=_components(g)
    # Locate the long L-shaped color key: a component with extended horizontal
    # and vertical arms sharing an endpoint.
    key=None; best=-1
    for col,pts in comps:
        if len(pts)<5: continue
        s=set(pts); score=0
        for r,c in pts:
            hr=sum((r,x) in s for x in range(len(g[0])))
            vr=sum((y,c) in s for y in range(len(g)))
            score=max(score, min(hr,vr)*10 + hr+vr)
        if score>best:
            best=score; key=col
    if key is None: return g
    # Find an exact shape duplicate across colors. Recolor the non-key copy;
    # zero is used as a shape stencil and is not the object to overwrite.
    shapes=[(col,pts,_norm(pts)) for col,pts in comps]
    for i,(ca,pa,sa) in enumerate(shapes):
        for cb,pb,sb in shapes[i+1:]:
            if ca==cb or len(pa)!=len(pb): continue
            if sb not in _variants(sa): continue
            candidates=[]
            if ca != key and ca != 0: candidates.append((ca,pa))
            if cb != key and cb != 0: candidates.append((cb,pb))
            if not candidates:
                if ca != key: candidates.append((ca,pa))
                if cb != key: candidates.append((cb,pb))
            if candidates:
                _, target=candidates[-1]
                for r,c in target: g[r][c]=key
                return g
    return g

